def can_have_consecutive_days(day1, day2):
    days_of_week = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
    day1_index = days_of_week.index(day1)
    day2_index = days_of_week.index(day2)

    # Check if the days are consecutive or wrap around from Sunday to Monday
    return abs(day1_index - day2_index) == 1 or (day1_index == 6 and day2_index == 0) or (day1_index == 0 and day2_index == 6)

def main():
    import sys
    input = sys.stdin.read
    data = input().strip().split()
    day1, day2 = data[0], data[1]

    if can_have_consecutive_days(day1, day2):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()

